"""New MVP scope only. Local permission records are not generated by this module."""
import hashlib,json,time,uuid
from pathlib import Path
ROOT=Path(__file__).resolve().parent
OWNER=uuid.uuid4().hex

def claim_scope(approval,candidate_sha,*,now_ns=None,store=None,owner=OWNER):
    now=time.monotonic_ns() if now_ns is None else now_ns
    auth=json.loads(Path(approval).read_text(encoding='utf-8'))
    scope=auth.get('mvp_scope',{})
    start=scope.get('suite_started_monotonic_ns')
    if auth.get('status')!='APPROVED_EXACT_ARTIFACT' or auth.get('candidate_sha256')!=candidate_sha or scope.get('name')!='MVP-DEMO-V1_NON_MOTION' or scope.get('restart_policy')!='EXPLICIT_SAME_PROCESS_WITHIN_WINDOW' or type(start)is not int or not 0<=now-start<1800_000_000_000:
        raise PermissionError('fresh MVP candidate/non-motion/1800s scope missing or expired')
    suite=auth.get('suite_id')
    if not isinstance(suite,str) or not suite:raise PermissionError('suite identity missing')
    directory=Path(store) if store is not None else ROOT/'authorization_uses';directory.mkdir(parents=True,exist_ok=True)
    dest=directory/(hashlib.sha256(suite.encode()).hexdigest()+'.json')
    binding=dict(owner=owner,suite_id=suite,candidate_sha256=candidate_sha,started_ns=start)
    try:
        with dest.open('x',encoding='utf-8') as f:json.dump(binding,f)
    except FileExistsError:
        if json.loads(dest.read_text(encoding='utf-8'))!=binding:raise PermissionError('permission already owned/consumed by another process')
    return binding
